168→        });
169→      }
170→    }
171→
172→    // Custom tools loaded from JSON files are always local-only + execute.
173→    for (const tool of this.registry.list()) {
174→      if (tool.isCustom) {
175→        const entry = this.managed.get(tool.name);
176→        if (entry) {
177→          entry.policy = { localOnly: true, permission: 'execute' };
178→        }
179→      }
180→    }
181→  }
