188→  enable(name: string): boolean {
189→    const entry = this.managed.get(name);
190→    if (!entry) return false;
191→    entry.enabled = true;
192→    logger.info(`ToolManager: tool '${name}' enabled`);
193→    return true;
194→  }
195→
196→  /** Disables a tool — execute() will reject calls to it. */
197→  disable(name: string): boolean {
198→    const entry = this.managed.get(name);
199→    if (!entry) return false;
200→    entry.enabled = false;
201→    logger.info(`ToolManager: tool '${name}' disabled`);
202→    return true;
203→  }
