206→  isEnabled(name: string): boolean {
207→    return this.managed.get(name)?.enabled ?? false;
208→  }
209→
210→  // --------------------------------------------------------------------------
211→  // Policy Queries
212→  // --------------------------------------------------------------------------
213→
214→  /** Returns the policy for a registered tool, or undefined. */
215→  getPolicy(name: string): ToolPolicy | undefined {
216→    return this.managed.get(name)?.policy;
217→  }
218→
219→  /** Returns all tools flagged as local-only. */
220→  getLocalOnlyTools(): ManagedTool[] {
221→    return Array.from(this.managed.values()).filter((t) => t.policy.localOnly);
222→  }
223→
224→  // --------------------------------------------------------------------------
225→  // Usage Stats
226→  // --------------------------------------------------------------------------
227→
228→  /** Returns usage stats for a single tool. */
229→  getStats(name: string): ToolUsageStats | undefined {
230→    return this.managed.get(name)?.stats;
231→  }
232→
233→  /** Returns stats for all tools, keyed by tool name. */
234→  getAllStats(): Record<string, ToolUsageStats> {
235→    const out: Record<string, ToolUsageStats> = {};
236→    for (const [name, entry] of this.managed) {
237→      out[name] = { ...entry.stats };
238→    }
239→    return out;
240→  }
