242→  /** Computes the error rate (0–1) for a tool, or 0 if never invoked. */
243→  getErrorRate(name: string): number {
244→    const stats = this.managed.get(name)?.stats;
245→    if (!stats || stats.invocations === 0) return 0;
246→    return stats.failures / stats.invocations;
247→  }
248→
249→  // --------------------------------------------------------------------------
250→  // Execution
251→  // --------------------------------------------------------------------------
252→
253→  /**
254→   * Validates policy, checks enabled state, then delegates to the underlying
255→   * ToolRegistry for schema validation and handler invocation.
256→   */
257→  async execute(name: string, args: unknown, context?: ToolContext): Promise<ToolResult> {
258→    // Ensure we have the latest tools from registry
259→    this.syncFromRegistry();
260→
261→    const entry = this.managed.get(name);
262→    if (!entry) {
263→      return { success: false, output: `Tool '${name}' not found`, duration: 0 };
264→    }
265→
266→    // Enabled check
267→    if (!entry.enabled) {
268→      return {
269→        success: false,
270→        output: `Tool '${name}' is currently disabled`,
271→        duration: 0,
272→      };
273→    }
274→
275→    // Permission / local-only policy check
276→    const check = this.permissionPolicy.check(name, entry.policy);
277→    if (!check.allowed) {
278→      return { success: false, output: check.reason!, duration: 0 };
279→    }
280→
281→    // Delegate to registry (handles schema validation, danger-level, handler)
282→    const result = await this.registry.execute(name, args, context);
283→
284→    // Update stats
285→    entry.stats.invocations++;
286→    if (result.success) {
287→      entry.stats.successes++;
288→    } else {
289→      entry.stats.failures++;
290→    }
