68→   * Checks whether a tool with the given policy is allowed to execute.
69→   *
70→   * Enforcement order:
71→   * 1. Local-only tools are blocked in cloud environments.
72→   * 2. The tool's required permission must be granted.
73→   */
74→  check(toolName: string, policy: ToolPolicy): PermissionCheckResult {
75→    // Local-only enforcement
76→    if (policy.localOnly && this.environment !== 'local') {
77→      return {
