/**
 * @fileoverview Permission Policy Unit Tests
 *
 * Tests the PermissionPolicy class for local-only enforcement
 * and permission-level gating.
 */

import { describe, it, expect } from 'vitest';
import { PermissionPolicy } from '../../src/security/permissions.js';
import type { ToolPolicy } from '../../src/tools/types.js';

describe('PermissionPolicy', () => {
  describe('Environment', () => {
    it('should default to local', () => {
      const p = new PermissionPolicy();
      expect(p.getEnvironment()).toBe('local');
    });

    it('should accept cloud environment', () => {
      const p = new PermissionPolicy('cloud');
      expect(p.getEnvironment()).toBe('cloud');
    });

    it('should allow changing environment', () => {
      const p = new PermissionPolicy('local');
      p.setEnvironment('cloud');
      expect(p.getEnvironment()).toBe('cloud');
    });
  });

  describe('Permissions', () => {
    it('should grant all permissions by default', () => {
      const p = new PermissionPolicy();
      expect(p.getGrantedPermissions()).toContain('read');
      expect(p.getGrantedPermissions()).toContain('write');
      expect(p.getGrantedPermissions()).toContain('execute');
    });

    it('should allow revoking permissions', () => {
      const p = new PermissionPolicy();
      p.revoke('write');
      expect(p.getGrantedPermissions()).not.toContain('write');
    });

    it('should allow granting permissions', () => {
      const p = new PermissionPolicy('local', ['read']);
      expect(p.getGrantedPermissions()).not.toContain('write');
      p.grant('write');
      expect(p.getGrantedPermissions()).toContain('write');
    });
  });

  describe('check()', () => {
    const localOnlyWrite: ToolPolicy = { localOnly: true, permission: 'write' };
    const localOnlyRead: ToolPolicy = { localOnly: true, permission: 'read' };
    const remoteRead: ToolPolicy = { localOnly: false, permission: 'read' };

    it('should allow local-only tool in local environment', () => {
      const p = new PermissionPolicy('local');
      const result = p.check('workspace_create', localOnlyWrite);
      expect(result.allowed).toBe(true);
    });

    it('should block local-only tool in cloud environment', () => {
      const p = new PermissionPolicy('cloud');
      const result = p.check('workspace_create', localOnlyWrite);
      expect(result.allowed).toBe(false);
      expect(result.reason).toContain('local-only');
      expect(result.reason).toContain('cloud');
    });

    it('should allow non-local tool in cloud environment', () => {
      const p = new PermissionPolicy('cloud');
      const result = p.check('web_fetch', remoteRead);
      expect(result.allowed).toBe(true);
    });

    it('should block tool when required permission not granted', () => {
      const p = new PermissionPolicy('local', ['read']);
      const result = p.check('workspace_create', localOnlyWrite);
      expect(result.allowed).toBe(false);
      expect(result.reason).toContain('write');
      expect(result.reason).toContain('permission');
    });

    it('should allow tool when required permission is granted', () => {
      const p = new PermissionPolicy('local', ['read']);
      const result = p.check('workspace_list', localOnlyRead);
      expect(result.allowed).toBe(true);
    });

    it('should check local-only before permissions', () => {
      // Cloud + missing permission — should report local-only, not permission
      const p = new PermissionPolicy('cloud', ['read']);
      const result = p.check('workspace_create', localOnlyWrite);
      expect(result.allowed).toBe(false);
      expect(result.reason).toContain('local-only');
    });
  });
});

