/**
 * @fileoverview `/pm` command handler.
 *
 * Routes `/pm list`, `/pm view`, `/pm comment`, `/pm update` subcommands.
 *
 * @module commands/pm
 */

import type { Session } from '../session/types.js';
import type { CommandResult } from './types.js';

/**
 * Handle `/pm` command and subcommands.
 */
export function handlePM(args: string[], session: Session): CommandResult {
  const sub = args[0]?.toLowerCase();

  switch (sub) {
    case 'list':
    case 'view':
    case 'comment':
    case 'update':
      return {
        handled: true,
        shouldProcess: false,
        text: `PM integration not yet implemented. Subcommand: ${sub}`,
      };

    default:
      return {
        handled: true,
        shouldProcess: false,
        text: 'Usage: /pm <list|view|comment|update> [args]',
      };
  }
}

